package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/reports") public class ReportServlet extends HttpServlet{protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){String scope=Access.isAdmin(u)?"1=1":"s.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)";String dscope=Access.isAdmin(u)?"1=1":"d.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)";req.setAttribute("department",group(c,"SELECT d.department_name,COUNT(s.staff_id) FROM departments d LEFT JOIN staff s ON d.department_id=s.department_id AND s.status='ACTIVE' WHERE "+(Access.isAdmin(u)?"1=1":"d.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)")+" GROUP BY d.department_id,d.department_name"));req.setAttribute("workload",group(c,"SELECT s.name,COUNT(da.assignment_id) FROM staff s LEFT JOIN duty_assignments da ON s.staff_id=da.staff_id WHERE "+scope+" GROUP BY s.staff_id,s.name ORDER BY COUNT(da.assignment_id) DESC LIMIT 10"));req.setAttribute("dutyStats",scalar(c,dscope,u));req.getRequestDispatcher("/reports.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 private List<Map<String,Object>>group(Connection c,String q)throws Exception{List<Map<String,Object>>l=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("name",r.getString(1));m.put("value",r.getInt(2));l.add(m);}}return l;}
 private Map<String,Integer>scalar(Connection c,String dscope,User u)throws Exception{Map<String,Integer>m=new LinkedHashMap<>();String staffScope=Access.isAdmin(u)?"1=1":"s.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)";String[][]q={{"Total duties","SELECT COUNT(*) FROM duties d WHERE "+dscope},{"Completed","SELECT COUNT(*) FROM duties d WHERE d.status='COMPLETED' AND "+dscope},{"Pending","SELECT COUNT(*) FROM duties d WHERE d.status IN ('OPEN','ASSIGNED','IN_PROGRESS') AND "+dscope},{"Cancelled","SELECT COUNT(*) FROM duties d WHERE d.status='CANCELLED' AND "+dscope},{"Approved leave","SELECT COUNT(*) FROM leaves l JOIN staff s ON l.staff_id=s.staff_id WHERE l.status='APPROVED' AND "+staffScope}};for(String[]x:q)try(Statement st=c.createStatement();ResultSet r=st.executeQuery(x[1])){r.next();m.put(x[0],r.getInt(1));}return m;} }
